/**
 * The only code in Stoat that talks to PayPal.
 *
 * Orders and captures go through the official PayPal Server SDK (generated by
 * APIMatic): Orders v2 against the Sandbox or Live host chosen by PAYPAL_BASE_URL.
 * Webhook signature verification uses PayPal's REST endpoint because the SDK does
 * not wrap it. There is no simulated mode: without credentials every call fails with
 * PAYPAL_NOT_CONFIGURED rather than inventing an order.
 */
import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  MobileReturnFlow,
  OrdersController,
  PaymentsController,
  PaypalExperienceUserAction, PaypalWalletContextShippingPreference,
} from "@paypal/paypal-server-sdk";
import { StoatError, ValidationError } from "../../common/errors.js";
import { toDecimalString } from "../../common/decimal.js";

export interface PayPalConfig {
  clientId: string;
  clientSecret: string;
  baseUrl: string;
  webhookId?: string;
  returnUrl?: string;
  cancelUrl?: string;
}

export interface GatewayOrder {
  id: string;
  status: string;
  approveUrl: string | null;
}

export interface GatewayCapture {
  orderId: string;
  orderStatus: string;
  captureId: string | null;
  captureStatus: string | null;
  amount: string | null;
  currency: string | null;
  customId: string | null;
  /** seller_receivable_breakdown.paypal_fee, when PayPal reports it. */
  paypalFee?: string | null;
  /** Capture create_time, used for the refund window. */
  createTime?: string | null;
}

export interface GatewayRefundState {
  refundId: string;
  status: string;
  amount: string | null;
  currency: string | null;
  captureId: string | null;
}

export interface GatewayRefund {
  refundId: string;
  status: string;
}

export interface PayoutItemInput {
  senderItemId: string;
  receiver: string;
  amount: string;
  currency: string;
  note: string;
}

export interface GatewayPayout {
  batchId: string;
  batchStatus: string;
  items: { senderItemId: string; itemId: string | null; status: string; reason: string | null }[];
}

export interface WebhookVerifyInput {
  headers: Record<string, string | undefined>;
  event: unknown;
}

/** What the service needs from PayPal. Production uses SdkPayPalGateway only. */
export interface PayPalGateway {
  readonly environment: "sandbox" | "live";
  createOrder(input: {
    amount: string;
    currency: string;
    customId: string;
    invoiceId: string;
    description: string;
    requestId: string;
    /** Browser user agent of the buyer. On mobile it lets PayPal open the PayPal app (app switch). */
    buyerUserAgent?: string;
  }): Promise<GatewayOrder>;
  refundCapture(input: { captureId: string; amount: string; currency: string; requestId: string; note: string; invoiceId?: string }): Promise<GatewayRefund>;
  captureOrder(orderId: string, requestId: string): Promise<GatewayCapture>;
  getOrder(orderId: string): Promise<GatewayCapture>;
  /** Read one capture (PaymentsController.getCapturedPayment). */
  getCapture(captureId: string): Promise<GatewayCapture>;
  /** Read one refund (PaymentsController.getRefund). */
  getRefund(refundId: string): Promise<GatewayRefundState>;
  /** Pay providers through the PayPal Payouts API. senderBatchId is the idempotency key. */
  createPayout(input: { senderBatchId: string; emailSubject: string; items: PayoutItemInput[] }): Promise<GatewayPayout>;
  getPayout(batchId: string): Promise<GatewayPayout>;
  verifyWebhook(input: WebhookVerifyInput): Promise<boolean>;
}

export class PayPalNotConfiguredError extends StoatError {
  constructor() {
    super(
      "PAYPAL_NOT_CONFIGURED",
      "PayPal is not configured. Set PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET (Sandbox REST app credentials).",
      503,
    );
  }
}

export class PayPalApiError extends StoatError {
  constructor(code: string, message: string, statusCode: number, details?: Record<string, any>) {
    super(code, message, statusCode, details);
  }
}

/**
 * PayPal amounts carry at most 2 decimals for the currencies Stoat uses. Stoat stores 6, so a
 * value with significant digits past the second is refused instead of being silently rounded.
 */
export function toPayPalAmount(amount: string | number, what = 'Amount'): string {
  const [whole, frac = ''] = toDecimalString(amount).split('.');
  if (/[1-9]/.test(frac.slice(2))) {
    throw new ValidationError(`${what} ${amount} has more than 2 decimal places; PayPal cannot move it exactly.`);
  }
  return `${whole}.${frac.slice(0, 2).padEnd(2, '0')}`;
}

/** Client-credentials token. Used by the gateway and by the operator scripts. */
export async function fetchPayPalToken(cfg: PayPalConfig): Promise<{ accessToken: string; expiresIn: number; scopes: string[] }> {
  const res = await fetch(`${cfg.baseUrl}/v1/oauth2/token`, {
    method: 'POST',
    headers: {
      Authorization: `Basic ${Buffer.from(`${cfg.clientId}:${cfg.clientSecret}`).toString('base64')}`,
      'Content-Type': 'application/x-www-form-urlencoded',
    },
    body: 'grant_type=client_credentials',
    signal: AbortSignal.timeout(10_000),
  });
  const body = (await res.json().catch(() => ({}))) as { access_token?: string; expires_in?: number; scope?: string; error?: string };
  if (!res.ok || !body.access_token) {
    throw new PayPalApiError('PAYPAL_AUTH_FAILED', `PayPal did not issue a token (HTTP ${res.status}${body.error ? ', ' + body.error : ''}).`, 502);
  }
  return { accessToken: body.access_token, expiresIn: body.expires_in ?? 300, scopes: String(body.scope ?? '').split(' ').filter(Boolean) };
}

/** Per-call PayPal timeout in ms: PAYPAL_TIMEOUT_MS, default 30000. */
export function payPalTimeoutMs(env: NodeJS.ProcessEnv = process.env): number {
  const n = Number(env.PAYPAL_TIMEOUT_MS);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : 30_000;
}

export function readPayPalConfig(env: NodeJS.ProcessEnv = process.env): PayPalConfig | null {
  const clientId = env.PAYPAL_CLIENT_ID?.trim();
  const clientSecret = env.PAYPAL_CLIENT_SECRET?.trim();
  if (!clientId || !clientSecret) return null;
  return {
    clientId,
    clientSecret,
    baseUrl: (env.PAYPAL_BASE_URL?.trim() || "https://api-m.sandbox.paypal.com").replace(/\/+$/, ""),
    webhookId: env.PAYPAL_WEBHOOK_ID?.trim() || undefined,
    returnUrl: env.PAYPAL_RETURN_URL?.trim() || undefined,
    cancelUrl: env.PAYPAL_CANCEL_URL?.trim() || undefined,
  };
}

/** Translate an SDK failure into a Stoat error the API can return. Never leaks secrets. */
function translate(err: unknown, action: string): never {
  if (err instanceof StoatError) throw err;
  if (err instanceof ApiError) {
    const body = (err.result ?? {}) as { name?: string; message?: string; details?: { issue?: string; description?: string }[]; debug_id?: string };
    const issue = body.details?.[0]?.issue ?? body.name ?? `HTTP_${err.statusCode}`;
    const description = body.details?.[0]?.description ?? body.message ?? "PayPal rejected the request.";
    const details = { paypal_issue: issue, paypal_debug_id: body.debug_id, paypal_status: err.statusCode };
    if (issue === "ORDER_NOT_APPROVED") {
      throw new PayPalApiError("PAYPAL_ORDER_NOT_APPROVED", "The buyer has not approved this PayPal order yet. Open the approval link, approve the payment, then capture.", 409, details);
    }
    if (err.statusCode === 401) {
      throw new PayPalApiError("PAYPAL_AUTH_FAILED", "PayPal rejected the configured credentials. Check PAYPAL_CLIENT_ID, PAYPAL_CLIENT_SECRET and that PAYPAL_BASE_URL matches the app environment.", 502, details);
    }
    throw new PayPalApiError("PAYPAL_REQUEST_REJECTED", `PayPal could not ${action}: ${description}`, err.statusCode >= 500 ? 502 : 422, details);
  }
  throw new PayPalApiError("PAYPAL_UNREACHABLE", `Could not reach PayPal to ${action}. Try again shortly.`, 502);
}

export class SdkPayPalGateway implements PayPalGateway {
  readonly environment: "sandbox" | "live";
  private orders: OrdersController;
  private payments: PaymentsController;
  private tokenCache?: { token: string; expiresAt: number };

  constructor(private cfg: PayPalConfig) {
    this.environment = /sandbox/i.test(cfg.baseUrl) ? "sandbox" : "live";
    const client = new Client({
      clientCredentialsAuthCredentials: { oAuthClientId: cfg.clientId, oAuthClientSecret: cfg.clientSecret },
      timeout: payPalTimeoutMs(),
      environment: this.environment === "sandbox" ? Environment.Sandbox : Environment.Production,
    });
    this.orders = new OrdersController(client);
    this.payments = new PaymentsController(client);
  }

  async createOrder(input: { amount: string; currency: string; customId: string; invoiceId: string; description: string; requestId: string; buyerUserAgent?: string }): Promise<GatewayOrder> {
    try {
      const { result } = await this.orders.createOrder({
        paypalRequestId: input.requestId,
        prefer: "return=representation",
        body: {
          intent: CheckoutPaymentIntent.Capture,
          purchaseUnits: [
            {
              amount: { currencyCode: input.currency, value: input.amount },
              customId: input.customId,
              invoiceId: input.invoiceId,
              description: input.description.slice(0, 127),
            },
          ],
          paymentSource: {
            paypal: {
              experienceContext: {
                brandName: "Stoat",
                userAction: PaypalExperienceUserAction.PayNow,
                shippingPreference: PaypalWalletContextShippingPreference.NoShipping,
                ...(input.buyerUserAgent && /Android|iPhone|iPad|Mobile/i.test(input.buyerUserAgent)
                  ? { appSwitchContext: { mobileWeb: { returnFlow: MobileReturnFlow.Auto, buyerUserAgent: input.buyerUserAgent.slice(0, 512) } } }
                  : {}),
                ...(this.cfg.returnUrl ? { returnUrl: this.cfg.returnUrl } : {}),
                ...(this.cfg.cancelUrl ? { cancelUrl: this.cfg.cancelUrl } : {}),
              },
            },
          },
        },
      });
      const approve = result.links?.find((l) => l.rel === "payer-action" || l.rel === "approve");
      if (!result.id) throw new PayPalApiError("PAYPAL_BAD_RESPONSE", "PayPal returned an order without an id.", 502);
      return { id: result.id, status: String(result.status ?? "CREATED"), approveUrl: approve?.href ?? null };
    } catch (err) {
      return translate(err, "create the order");
    }
  }

  private toCapture(r: Awaited<ReturnType<OrdersController["captureOrder"]>>["result"]): GatewayCapture {
    const unit = r.purchaseUnits?.[0];
    const cap = unit?.payments?.captures?.[0];
    return {
      orderId: r.id ?? "",
      orderStatus: String(r.status ?? ""),
      captureId: cap?.id ?? null,
      captureStatus: cap?.status ? String(cap.status) : null,
      amount: cap?.amount?.value ?? null,
      currency: cap?.amount?.currencyCode ?? null,
      customId: cap?.customId ?? unit?.customId ?? null,
      paypalFee: cap?.sellerReceivableBreakdown?.paypalFee?.value ?? null,
      createTime: cap?.createTime ?? null,
    };
  }

  async captureOrder(orderId: string, requestId: string): Promise<GatewayCapture> {
    try {
      const { result } = await this.orders.captureOrder({ id: orderId, paypalRequestId: requestId, prefer: "return=representation" });
      return this.toCapture(result);
    } catch (err) {
      if (err instanceof ApiError) {
        const issue = ((err.result ?? {}) as { details?: { issue?: string }[] }).details?.[0]?.issue;
        if (issue === "ORDER_ALREADY_CAPTURED") return this.getOrder(orderId);
      }
      return translate(err, "capture the order");
    }
  }

  async refundCapture(input: { captureId: string; amount: string; currency: string; requestId: string; note: string; invoiceId?: string }): Promise<GatewayRefund> {
    try {
      const { result } = await this.payments.refundCapturedPayment({
        captureId: input.captureId,
        paypalRequestId: input.requestId,
        prefer: "return=representation",
        body: {
          amount: { currencyCode: input.currency, value: input.amount },
          noteToPayer: input.note.slice(0, 255),
          ...(input.invoiceId ? { invoiceId: input.invoiceId } : {}),
        },
      });
      if (!result.id) throw new PayPalApiError("PAYPAL_BAD_RESPONSE", "PayPal returned a refund without an id.", 502);
      return { refundId: result.id, status: String(result.status ?? "") };
    } catch (err) {
      return translate(err, "refund the payment");
    }
  }

  async getOrder(orderId: string): Promise<GatewayCapture> {
    try {
      const { result } = await this.orders.getOrder({ id: orderId });
      return this.toCapture(result);
    } catch (err) {
      return translate(err, "read the order");
    }
  }

  async getCapture(captureId: string): Promise<GatewayCapture> {
    try {
      const { result: c } = await this.payments.getCapturedPayment({ captureId });
      if (!c.id) throw new PayPalApiError('PAYPAL_BAD_RESPONSE', 'PayPal returned a capture without an id.', 502);
      const up = c.links?.find((l) => l.rel === 'up')?.href;
      return {
        orderId: up ? decodeURIComponent(up.split('/').pop() ?? '') : '',
        orderStatus: '',
        captureId: c.id,
        captureStatus: c.status ? String(c.status) : null,
        amount: c.amount?.value ?? null,
        currency: c.amount?.currencyCode ?? null,
        customId: c.customId ?? null,
        paypalFee: c.sellerReceivableBreakdown?.paypalFee?.value ?? null,
        createTime: c.createTime ?? null,
      };
    } catch (err) {
      return translate(err, 'read the capture');
    }
  }

  async getRefund(refundId: string): Promise<GatewayRefundState> {
    try {
      const { result: r } = await this.payments.getRefund({ refundId });
      if (!r.id) throw new PayPalApiError('PAYPAL_BAD_RESPONSE', 'PayPal returned a refund without an id.', 502);
      const up = r.links?.find((l) => l.rel === 'up')?.href;
      return {
        refundId: r.id,
        status: String(r.status ?? ''),
        amount: r.amount?.value ?? null,
        currency: r.amount?.currencyCode ?? null,
        captureId: up ? decodeURIComponent(up.split('/').pop() ?? '') || null : null,
      };
    } catch (err) {
      return translate(err, 'read the refund');
    }
  }

  private mapPayout(body: any): GatewayPayout {
    const header = body?.batch_header ?? {};
    const items = (body?.items ?? []) as any[];
    return {
      batchId: String(header.payout_batch_id ?? ''),
      batchStatus: String(header.batch_status ?? ''),
      items: items.map((i) => ({
        senderItemId: String(i.payout_item?.sender_item_id ?? ''),
        itemId: i.payout_item_id ?? null,
        status: String(i.transaction_status ?? ''),
        reason: i.errors?.message ?? i.errors?.name ?? null,
      })),
    };
  }

  private async payoutsFetch(path: string, init: { method: string; body?: unknown; requestId?: string }, action: string): Promise<any> {
    let res: Response;
    try {
      res = await fetch(`${this.cfg.baseUrl}${path}`, {
        method: init.method,
        headers: {
          Authorization: `Bearer ${await this.accessToken()}`,
          'Content-Type': 'application/json',
          ...(init.requestId ? { 'PayPal-Request-Id': init.requestId } : {}),
        },
        body: init.body ? JSON.stringify(init.body) : undefined,
        signal: AbortSignal.timeout(payPalTimeoutMs()),
      });
    } catch {
      throw new PayPalApiError('PAYPAL_UNREACHABLE', `Could not reach PayPal to ${action}. Try again shortly.`, 502);
    }
    const body: any = await res.json().catch(() => ({}));
    if (!res.ok) {
      const issue = body?.name ?? `HTTP_${res.status}`;
      if (res.status === 401) throw new PayPalApiError('PAYPAL_AUTH_FAILED', 'PayPal rejected the configured credentials.', 502, { paypal_issue: issue });
      if (res.status === 403 || issue === 'PAYOUTS_NOT_ENABLED' || issue === 'NOT_AUTHORIZED') {
        throw new PayPalApiError('PAYPAL_PAYOUTS_NOT_ENABLED', 'This PayPal app is not allowed to send payouts. Enable "Payouts" on the REST app in the PayPal developer dashboard.', 403, { paypal_issue: issue, paypal_debug_id: body?.debug_id });
      }
      throw new PayPalApiError('PAYPAL_PAYOUT_REJECTED', `PayPal could not ${action}: ${body?.message ?? issue}`, res.status >= 500 ? 502 : 422, { paypal_issue: issue, paypal_debug_id: body?.debug_id, details: body?.details });
    }
    return body;
  }

  async createPayout(input: { senderBatchId: string; emailSubject: string; items: PayoutItemInput[] }): Promise<GatewayPayout> {
    const created = await this.payoutsFetch('/v1/payments/payouts', {
      method: 'POST',
      requestId: input.senderBatchId,
      body: {
        sender_batch_header: { sender_batch_id: input.senderBatchId, email_subject: input.emailSubject.slice(0, 120), recipient_type: 'EMAIL' },
        items: input.items.map((i) => ({
          recipient_type: 'EMAIL', receiver: i.receiver, amount: { value: i.amount, currency: i.currency },
          note: i.note.slice(0, 160), sender_item_id: i.senderItemId,
        })),
      },
    }, 'create the payout');
    const batchId = created?.batch_header?.payout_batch_id;
    if (!batchId) throw new PayPalApiError('PAYPAL_BAD_RESPONSE', 'PayPal returned a payout without an id.', 502);
    return this.getPayout(String(batchId));
  }

  async getPayout(batchId: string): Promise<GatewayPayout> {
    return this.mapPayout(await this.payoutsFetch(`/v1/payments/payouts/${encodeURIComponent(batchId)}`, { method: 'GET' }, 'read the payout'));
  }

  private async accessToken(): Promise<string> {
    if (this.tokenCache && this.tokenCache.expiresAt > Date.now() + 30_000) return this.tokenCache.token;
    const { accessToken, expiresIn } = await fetchPayPalToken(this.cfg);
    this.tokenCache = { token: accessToken, expiresAt: Date.now() + expiresIn * 1000 };
    return accessToken;
  }

  /** True only when PayPal itself answers verification_status SUCCESS. Fails closed. */
  async verifyWebhook({ headers, event }: WebhookVerifyInput): Promise<boolean> {
    const webhookId = this.cfg.webhookId;
    const h = (n: string) => headers[n] ?? headers[n.toUpperCase()];
    const authAlgo = h("paypal-auth-algo");
    const certUrl = h("paypal-cert-url");
    const transmissionId = h("paypal-transmission-id");
    const transmissionSig = h("paypal-transmission-sig");
    const transmissionTime = h("paypal-transmission-time");
    if (!webhookId || !authAlgo || !certUrl || !transmissionId || !transmissionSig || !transmissionTime) return false;
    try {
      const res = await fetch(`${this.cfg.baseUrl}/v1/notifications/verify-webhook-signature`, {
        method: "POST",
        headers: { Authorization: `Bearer ${await this.accessToken()}`, "Content-Type": "application/json" },
        body: JSON.stringify({
          auth_algo: authAlgo,
          cert_url: certUrl,
          transmission_id: transmissionId,
          transmission_sig: transmissionSig,
          transmission_time: transmissionTime,
          webhook_id: webhookId,
          webhook_event: event,
        }),
        signal: AbortSignal.timeout(10_000),
      });
      if (!res.ok) return false;
      return ((await res.json()) as { verification_status?: string }).verification_status === "SUCCESS";
    } catch {
      return false;
    }
  }
}

/** Gateway used when credentials are missing: every call fails loudly and honestly. */
export class UnconfiguredPayPalGateway implements PayPalGateway {
  readonly environment = "sandbox" as const;
  async createOrder(): Promise<GatewayOrder> { throw new PayPalNotConfiguredError(); }
  async captureOrder(): Promise<GatewayCapture> { throw new PayPalNotConfiguredError(); }
  async getOrder(): Promise<GatewayCapture> { throw new PayPalNotConfiguredError(); }
  async getCapture(): Promise<GatewayCapture> { throw new PayPalNotConfiguredError(); }
  async getRefund(): Promise<GatewayRefundState> { throw new PayPalNotConfiguredError(); }
  async refundCapture(): Promise<GatewayRefund> { throw new PayPalNotConfiguredError(); }
  async createPayout(): Promise<GatewayPayout> { throw new PayPalNotConfiguredError(); }
  async getPayout(): Promise<GatewayPayout> { throw new PayPalNotConfiguredError(); }
  async verifyWebhook(): Promise<boolean> { return false; }
}

let shared: { key: string; gateway: PayPalGateway } | undefined;
/** One SDK client per process (keeps the OAuth token cached). Rebuilt if env changes. */
export function getPayPalGateway(): PayPalGateway {
  const cfg = readPayPalConfig();
  if (!cfg) return new UnconfiguredPayPalGateway();
  const key = JSON.stringify(cfg);
  if (!shared || shared.key !== key) shared = { key, gateway: new SdkPayPalGateway(cfg) };
  return shared.gateway;
}

export function payPalStatus(): { configured: boolean; environment: "sandbox" | "live" | null; webhook_configured: boolean } {
  const cfg = readPayPalConfig();
  if (!cfg) return { configured: false, environment: null, webhook_configured: false };
  return { configured: true, environment: /sandbox/i.test(cfg.baseUrl) ? "sandbox" : "live", webhook_configured: !!cfg.webhookId };
}
